module {
  phys.machine @a {
    phys.resource_class @q {
      kind = "qubit", count = 1 : i64, native_actions = []
    }
  }
  phys.resource @q0 {kind = "qubit", resource_class = @q, index = 0 : i64}
  phys.graph @g on @a : () -> () {
    phys.return
